"""Persistence layer for the todo CLI.

Todos are stored in a JSON file with the shape::

    {"next_id": <int>, "todos": [{"id": int, "text": str, "done": bool}, ...]}

``next_id`` is persisted so ids are never reused, even after deletion.
"""

import json
import os


class TodoStore:
    """Stores todos in a JSON file, persisting on every mutation."""

    def __init__(self, path):
        self.path = path
        self.todos = []
        self.next_id = 1
        if os.path.exists(path):
            self._load()

    def _load(self):
        with open(self.path, "r", encoding="utf-8") as f:
            content = f.read().strip()
        if not content:
            return
        data = json.loads(content)
        self.todos = data.get("todos", [])
        self.next_id = data.get("next_id", 1)
        # Sanity: never reuse an id that is still present.
        if self.todos:
            self.next_id = max(self.next_id, max(t["id"] for t in self.todos) + 1)

    def _save(self):
        tmp = self.path + ".tmp"
        with open(tmp, "w", encoding="utf-8") as f:
            json.dump({"next_id": self.next_id, "todos": self.todos}, f, indent=2)
        os.replace(tmp, self.path)

    def add(self, text):
        """Append a new todo, persist, and return its id."""
        todo = {"id": self.next_id, "text": text, "done": False}
        self.todos.append(todo)
        self.next_id += 1
        self._save()
        return todo["id"]

    def list(self, include_done=True):
        """Return todos in insertion order (only open ones when include_done is False)."""
        if include_done:
            return [dict(t) for t in self.todos]
        return [dict(t) for t in self.todos if not t["done"]]

    def complete(self, todo_id):
        """Mark a todo done and persist; return False if no such id."""
        for todo in self.todos:
            if todo["id"] == todo_id:
                todo["done"] = True
                self._save()
                return True
        return False

    def remove(self, todo_id):
        """Delete a todo and persist; return False if no such id."""
        for i, todo in enumerate(self.todos):
            if todo["id"] == todo_id:
                del self.todos[i]
                self._save()
                return True
        return False

"""Persistence layer for the todo CLI.

Todos are stored in a JSON file as:

    {"todos": [{"id": 1, "text": "...", "done": false}, ...], "next_id": 4}

``next_id`` is persisted explicitly so that ids are never reused, even after
the todo that currently holds the highest id is removed.
"""

import json
import os


class TodoStore:
    def __init__(self, path):
        self.path = path
        self.todos = []
        self._next_id = 1
        if os.path.exists(path):
            with open(self.path, "r", encoding="utf-8") as f:
                data = json.load(f)
            self.todos = data.get("todos", [])
            self._next_id = data.get("next_id", 1)
            # Defensive: never go backwards even if the file is hand-edited.
            if self.todos:
                self._next_id = max(self._next_id, max(t["id"] for t in self.todos) + 1)

    def _save(self):
        with open(self.path, "w", encoding="utf-8") as f:
            json.dump({"todos": self.todos, "next_id": self._next_id}, f)

    def add(self, text):
        """Append a new todo, persist, and return its id."""
        todo = {"id": self._next_id, "text": text, "done": False}
        self._next_id += 1
        self.todos.append(todo)
        self._save()
        return todo["id"]

    def list(self, include_done=True):
        """Return todos in insertion order (only open ones when include_done is False)."""
        if include_done:
            return list(self.todos)
        return [t for t in self.todos if not t["done"]]

    def complete(self, todo_id):
        """Mark the todo done and persist; return False if no such id."""
        for todo in self.todos:
            if todo["id"] == todo_id:
                todo["done"] = True
                self._save()
                return True
        return False

    def remove(self, todo_id):
        """Delete the todo and persist; return False if no such id."""
        for i, todo in enumerate(self.todos):
            if todo["id"] == todo_id:
                del self.todos[i]
                self._save()
                return True
        return False
